theorem tendsto_im_local_log {L : ℂ → ℂ} {b : ℂ} {r : ℝ}
    (hL : ContinuousOn L (Metric.ball b r ∩ {s : ℂ | 1 / 2 ≤ s.re})) {x : ℝ}
    (hx : vpt (1 / 2) x ∈ Metric.ball b r) :
    Tendsto (fun σ : ℝ => (L (vpt σ x)).im) (𝓝[>] (1 / 2)) (𝓝 (L (vpt (1 / 2) x)).im)

